var list_courses_default = defineTool({
  name: "list_courses",
  title: "Listar cursos",
  description: "Lista os cursos publicados da Tropa Cient\xEDfica, com trilha, n\xEDvel, dura\xE7\xE3o e se s\xE3o gratuitos. Aceita busca por texto.",
  inputSchema: {
    search: z.string().trim().nullable().describe("Texto opcional para filtrar por t\xEDtulo."),
    limit: z.number().int().nullable().describe("M\xE1ximo de cursos retornados (padr\xE3o 25).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ search, limit }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "N\xE3o autenticado." }], isError: true };
    }
    const supabase = supabaseForUser(ctx);
    let query = supabase.from("courses").select("id, slug, title, summary, level, duration_min, is_free, status, trail_id, instructor_name").eq("status", "published").order("order_index", { ascending: true }).limit(Math.min(Math.max(limit ?? 25, 1), 100));
    if (search) query = query.ilike("title", `%${search}%`);
    const { data, error } = await query;
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [{ type: "text", text: JSON.stringify(data ?? []) }],
      structuredContent: { courses: data ?? [] }
    };
  }
});

