// src/lib/mcp/tools/get-portfolio.ts
var pub = (rows) => (Array.isArray(rows) ? rows : []).filter((r) => r?.visibility === "public");
var SECTIONS = {
  perfil: "01_Profile",
  bio: "02_Bio",
  publicacoes: "04_Publicacoes",
  anais: "05_Anais_CONACIPS",
  formacao: "06_Formacao",
  cursos: "07_Cursos",
  certificacoes: "08_Certificacoes",
  experiencia: "09_Experiencia",
  projetos: "10_Projetos",
  habilidades: "11_Skills",
  links: "13_Links"
};
function read(section) {
  const d = apos_master_default;
  const raw = d[SECTIONS[section]];
  if (section === "perfil" || section === "bio") return raw ?? null;
  return pub(raw);
}
var get_portfolio_default = defineTool6({
  name: "get_portfolio",
  title: "Consultar portf\xF3lio",
  description: "Retorna dados p\xFAblicos do portf\xF3lio de Matheus Florindo (perfil, bio, publica\xE7\xF5es, anais, forma\xE7\xE3o, cursos, certifica\xE7\xF5es, experi\xEAncia, projetos, habilidades e links), com busca opcional.",
  inputSchema: {
    section: z4.enum(["tudo", ...Object.keys(SECTIONS)]).describe("Se\xE7\xE3o desejada, ou 'tudo' para o portf\xF3lio completo."),
    search: z4.string().trim().nullable().describe("Texto opcional para filtrar itens.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ section, search }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "N\xE3o autenticado." }], isError: true };
    }
    const keys = section === "tudo" ? Object.keys(SECTIONS) : [section];
    const term = search?.toLowerCase();
    const result = {};
    for (const k of keys) {
      let value = read(k);
      if (term && Array.isArray(value)) {
        value = value.filter((r) => JSON.stringify(r).toLowerCase().includes(term));
      }
      result[k] = value;
    }
    const json = JSON.parse(JSON.stringify(result));
    return { content: [{ type: "text", text: JSON.stringify(json) }], structuredContent: json };
  }
});

